def solve_n_queens(n):
    def is_safe(board, row, col):
        for i in range(row):
            if board[i] == col or \
               board[i] - i == col - row or \
               board[i] + i == col + row:
                return False
        return True

    def backtrack(row, board):
        if row == n:
            return board
        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                result = backtrack(row + 1, board)
                if result:
                    return result
        return None

    return backtrack(0, [0] * n)

solution = solve_n_queens(26)
print(solution)

def is_valid_n_queens(solution):
    n = len(solution)
    # Check rows (implicit by the structure of the solution)
    # Check columns
    if len(set(solution)) != n:
        return False
    # Check diagonals
    for i in range(n):
        for j in range(i + 1, n):
            if abs(solution[i] - solution[j]) == abs(i - j):
                return False
    return True

solution = [0, 2, 4, 1, 3, 8, 10, 12, 14, 20, 22, 24, 19, 21, 23, 25, 9, 6, 15, 11, 7, 5, 17, 13, 18, 16]
print(is_valid_n_queens(solution))
